func newLabCluster(t *testing.T, size int) *labCluster {
	t.Helper()
	ports := freeClientPorts(t, 2*size)
	cluster := &labCluster{clientPorts: ports[:size], routePorts: ports[size:], stores: make([]string, size),
		runtimes: make([]*Runtime, size), routes: make([]string, size)}
	for index := range size {
		cluster.routes[index] = fmt.Sprintf("nats-route://127.0.0.1:%d", cluster.routePorts[index])
		cluster.stores[index] = filepath.Join(t.TempDir(), fmt.Sprintf("peer%d", index))
	}
	t.Cleanup(func() {
		for _, runtime := range cluster.runtimes {
			_ = runtime.Close()
		}
	})
	return cluster
}

func (cluster *labCluster) start(t *testing.T, ctx context.Context, index int) *Runtime {
	t.Helper()
	instance := fmt.Sprintf("peer%d", index)
	runtime, err := Start(ctx, Config{Cell: "lab", Instance: instance, Replicas: len(cluster.routes), Lab: true,
		Embedded: &Embedded{Host: "127.0.0.1", Port: cluster.clientPorts[index], RouteHost: "127.0.0.1",
			RoutePort: cluster.routePorts[index], Routes: PeerRoutes(cluster.routes, cluster.routes[index]),
			StoreDir: cluster.stores[index], BrokerIDs: []string{"peer0", "peer1", "peer2"}[:len(cluster.routes)]},
	})
	if err != nil {
		t.Fatal(err)
	}
	cluster.runtimes[index] = runtime
	return runtime
}

func (cluster *labCluster) stop(index int) {
	if cluster.runtimes[index] != nil {
		_ = cluster.runtimes[index].Close()
		cluster.runtimes[index] = nil
	}

func TestEmbeddedStoreLimit(t *testing.T) {
	embedded := &Embedded{Host: "127.0.0.1", Port: -1, StoreDir: t.TempDir()}
	cfg := Config{Cell: "lab", Instance: "one", Replicas: 1, Lab: true, Embedded: embedded}
	for _, test := range []struct {
		name  string
		limit int64
		want  int64
	}{
		{name: "default", want: DefaultStoreMaxBytes},
		{name: "configured", limit: 4 << 30, want: 4 << 30},
	} {
		t.Run(test.name, func(t *testing.T) {
			embedded.StoreMaxBytes = test.limit
			options, err := serverOptions(cfg)
			if err != nil {
				t.Fatal(err)
			}
			if options.JetStreamMaxStore != test.want {
				t.Fatalf("JetStream file limit = %d, want %d", options.JetStreamMaxStore, test.want)
			}
			// A rebooting peer must not log an ERR per reconnect attempt.
			if options.ReconnectErrorReports != 60 {
				t.Fatalf("route reconnect errors reported every %d attempts, want 60", options.ReconnectErrorReports)
			}
		})
	}
	embedded.StoreMaxBytes = -1
	if err := cfg.validate(); err == nil {
		t.Fatal("negative embedded store limit was accepted")
	}
	embedded.StoreMaxBytes = 0
	reserved := cfg
	reserved.Cell = "global"
	if err := reserved.validate(); err == nil {
		t.Fatal("the reserved global scope was accepted as a cell")
	}
}

func ValidateMembershipCredentials(path, cell, systemAccount string) error {
	if !cellName.MatchString(cell) || systemAccount == "" {
		return errors.New("membership credential cell or system account is invalid")
	}
	claim, public, err := credentialUser(path)
	if err != nil {
		return fmt.Errorf("membership credentials: %w", err)
	}
	publishes := slices.Clone([]string(claim.Pub.Allow))
	slices.Sort(publishes)
	if credentialAccount(claim) != systemAccount ||
		!slices.Equal(publishes, []string{MembershipMetaStepdownSubject, MembershipServerRemoveSubject}) ||
		len(claim.Pub.Deny) != 0 || len(claim.Sub.Allow) != 1 ||
		claim.Sub.Allow[0] != inboxPrefix(cell, public)+".>" || len(claim.Sub.Deny) != 0 ||
		claim.Resp != nil {
		return errors.New("membership credentials must have only server-remove, metadata step-down and private reply grants")
	}
	return nil
}
